import{_ as r,c as i,o,af as s}from"./chunks/framework.CVAsk1bH.js";const m=JSON.parse('{"title":"Progress Tracking","description":"Apps, tools, and methods to track your fitness and nutrition progress","frontmatter":{"title":"Progress Tracking","description":"Apps, tools, and methods to track your fitness and nutrition progress"},"headers":[],"relativePath":"guides/tracking.md","filePath":"guides/tracking.md"}'),a={name:"guides/tracking.md"};function t(n,e,l,g,c,d){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="progress-tracking" tabindex="-1">Progress Tracking <a class="header-anchor" href="#progress-tracking" aria-label="Permalink to “Progress Tracking”">​</a></h1><h2 id="essential-apps-tools" tabindex="-1">Essential Apps &amp; Tools <a class="header-anchor" href="#essential-apps-tools" aria-label="Permalink to “Essential Apps &amp; Tools”">​</a></h2><h3 id="workout-tracking" tabindex="-1">Workout Tracking <a class="header-anchor" href="#workout-tracking" aria-label="Permalink to “Workout Tracking”">​</a></h3><ul><li><strong><a href="https://flexify.net/" target="_blank" rel="noreferrer">Flexify</a></strong> - Track all gym sessions and progressive overload</li><li><strong>Features:</strong> Exercise history, weight progression, rest timers</li><li><strong>Why:</strong> Essential for ensuring you&#39;re progressing week to week</li></ul><h3 id="nutrition-tracking" tabindex="-1">Nutrition Tracking <a class="header-anchor" href="#nutrition-tracking" aria-label="Permalink to “Nutrition Tracking”">​</a></h3><ul><li><strong><a href="https://www.myfitnesspal.com/" target="_blank" rel="noreferrer">MyFitnessPal</a></strong> - Comprehensive food database</li><li><strong><a href="https://cronometer.com/" target="_blank" rel="noreferrer">Cronometer</a></strong> - More accurate micronutrient tracking</li><li><strong>Target:</strong> 2,100 calories daily, ~140g protein</li></ul><h3 id="body-composition" tabindex="-1">Body Composition <a class="header-anchor" href="#body-composition" aria-label="Permalink to “Body Composition”">​</a></h3><ul><li><strong>Body weight app</strong> - Daily weigh-ins with trend analysis</li><li><strong>Progress photos</strong> - Same lighting, pose, and time of day</li><li><strong>Measurements</strong> - Waist, chest, arms (monthly)</li><li><strong>How clothes fit</strong> - Most reliable day-to-day indicator</li></ul><h2 id="daily-tracking-protocol" tabindex="-1">Daily Tracking Protocol <a class="header-anchor" href="#daily-tracking-protocol" aria-label="Permalink to “Daily Tracking Protocol”">​</a></h2><h3 id="morning-routine" tabindex="-1">Morning Routine <a class="header-anchor" href="#morning-routine" aria-label="Permalink to “Morning Routine”">​</a></h3><ol><li><strong>Weigh yourself</strong> - Same time, after bathroom, before eating</li><li><strong>Log in body weight app</strong> - Focus on 7-day averages, not daily fluctuations</li><li><strong>Plan meals</strong> - Pre-log breakfast and lunch in tracking app</li></ol><h3 id="throughout-the-day" tabindex="-1">Throughout the Day <a class="header-anchor" href="#throughout-the-day" aria-label="Permalink to “Throughout the Day”">​</a></h3><ul><li><strong>Log meals immediately</strong> - Don&#39;t rely on memory</li><li><strong>Use food scale</strong> - Accuracy is crucial for 2,100 calorie target</li><li><strong>Pre-log snacks</strong> - Avoid impulse eating</li></ul><h3 id="evening-review" tabindex="-1">Evening Review <a class="header-anchor" href="#evening-review" aria-label="Permalink to “Evening Review”">​</a></h3><ul><li><strong>Complete food log</strong> - Ensure you hit calorie and protein targets</li><li><strong>Plan tomorrow&#39;s meals</strong> - Prep success starts with planning</li><li><strong>Log workout if completed</strong> - Record weights and reps in Flexify</li></ul><h2 id="weekly-assessment" tabindex="-1">Weekly Assessment <a class="header-anchor" href="#weekly-assessment" aria-label="Permalink to “Weekly Assessment”">​</a></h2><h3 id="body-composition-trends" tabindex="-1">Body Composition Trends <a class="header-anchor" href="#body-composition-trends" aria-label="Permalink to “Body Composition Trends”">​</a></h3><ul><li><strong>Weight trend</strong> - Looking for 0.5-1kg loss per week</li><li><strong>Progress photos</strong> - Same pose, lighting, and clothing weekly</li><li><strong>Energy levels</strong> - Should remain stable or improve</li><li><strong>Workout performance</strong> - Strength should maintain or improve</li></ul><h3 id="adherence-review" tabindex="-1">Adherence Review <a class="header-anchor" href="#adherence-review" aria-label="Permalink to “Adherence Review”">​</a></h3><ul><li><strong>Meal plan compliance</strong> - Aim for 80-90% adherence</li><li><strong>Workout consistency</strong> - Target 3 gym sessions per week</li><li><strong>Cardio completion</strong> - 2 sessions weekly once added</li><li><strong>Sleep quality</strong> - 7-9 hours consistently</li></ul><h2 id="monthly-deep-dive" tabindex="-1">Monthly Deep Dive <a class="header-anchor" href="#monthly-deep-dive" aria-label="Permalink to “Monthly Deep Dive”">​</a></h2><h3 id="comprehensive-assessment" tabindex="-1">Comprehensive Assessment <a class="header-anchor" href="#comprehensive-assessment" aria-label="Permalink to “Comprehensive Assessment”">​</a></h3><ul><li><strong>Body fat estimation</strong> - Progress photos comparison</li><li><strong>Strength progression</strong> - Review Flexify workout history</li><li><strong>Measurement changes</strong> - Waist, chest, arms with measuring tape</li><li><strong>Diet adherence analysis</strong> - Weekly average calories and protein</li></ul><h3 id="adjustment-indicators" tabindex="-1">Adjustment Indicators <a class="header-anchor" href="#adjustment-indicators" aria-label="Permalink to “Adjustment Indicators”">​</a></h3><p><strong>Consider reducing calories if:</strong></p><ul><li>Weight loss has stalled for 2+ weeks</li><li>Energy levels remain high</li><li>Workout performance is maintained</li></ul><p><strong>Consider diet break if:</strong></p><ul><li>Extreme fatigue develops</li><li>Strength drops significantly</li><li>Food obsession increases</li><li>Sleep quality deteriorates</li></ul><h2 id="key-performance-indicators" tabindex="-1">Key Performance Indicators <a class="header-anchor" href="#key-performance-indicators" aria-label="Permalink to “Key Performance Indicators”">​</a></h2><h3 id="nutrition-success-metrics" tabindex="-1">Nutrition Success Metrics <a class="header-anchor" href="#nutrition-success-metrics" aria-label="Permalink to “Nutrition Success Metrics”">​</a></h3><ul><li><strong>Daily calories:</strong> 2,100 target (±100 acceptable)</li><li><strong>Protein intake:</strong> 140g minimum daily</li><li><strong>Meal prep adherence:</strong> 5-6 days per week</li><li><strong>Hydration:</strong> 3-4L water daily</li></ul><h3 id="fitness-success-metrics" tabindex="-1">Fitness Success Metrics <a class="header-anchor" href="#fitness-success-metrics" aria-label="Permalink to “Fitness Success Metrics”">​</a></h3><ul><li><strong>Gym attendance:</strong> 3 sessions weekly</li><li><strong>Progressive overload:</strong> Weight increases every 2-3 weeks</li><li><strong>Flexibility consistency:</strong> Daily stretching routine</li><li><strong>Sports performance:</strong> Tennis/climbing improvements</li></ul><h3 id="body-composition-goals" tabindex="-1">Body Composition Goals <a class="header-anchor" href="#body-composition-goals" aria-label="Permalink to “Body Composition Goals”">​</a></h3><ul><li><strong>Monthly fat loss:</strong> 2-3% body fat reduction</li><li><strong>Overall target:</strong> 30% → 17% body fat (4 months)</li><li><strong>Weight loss rate:</strong> 0.5-1kg per week</li><li><strong>Muscle preservation:</strong> Strength maintained or improved</li></ul><h2 id="warning-signs-to-monitor" tabindex="-1">Warning Signs to Monitor <a class="header-anchor" href="#warning-signs-to-monitor" aria-label="Permalink to “Warning Signs to Monitor”">​</a></h2><h3 id="red-flags-seek-guidance" tabindex="-1">Red Flags - Seek Guidance <a class="header-anchor" href="#red-flags-seek-guidance" aria-label="Permalink to “Red Flags - Seek Guidance”">​</a></h3><ul><li><strong>Rapid strength loss</strong> - May indicate excessive calorie deficit</li><li><strong>Obsessive food thoughts</strong> - Consider a structured diet break</li><li><strong>Sleep disruption</strong> - Often first sign of overreaching</li><li><strong>Persistent fatigue</strong> - Body may need more calories</li><li><strong>Injury recurring</strong> - Review form and recovery protocols</li></ul><h3 id="plateau-breakers" tabindex="-1">Plateau Breakers <a class="header-anchor" href="#plateau-breakers" aria-label="Permalink to “Plateau Breakers”">​</a></h3><ul><li><strong>Refeed days</strong> - Higher calorie day every 2-3 weeks</li><li><strong>Exercise variation</strong> - New movements or intensities</li><li><strong>Calorie cycling</strong> - Higher calories on gym days, lower on rest days</li><li><strong>Diet break</strong> - 1-2 weeks at maintenance calories</li></ul><div class="tip custom-block"><p class="custom-block-title">Tracking Philosophy</p><p>Consistency in tracking is more important than perfection. Aim for 80-90% accuracy rather than obsessing over every gram. The trends matter more than daily fluctuations.</p></div><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to “Related Resources”">​</a></h2><ul><li><strong><a href="./../nutrition/meal-plan.html">Meal Plan</a></strong> - What to track for nutrition success</li><li><strong><a href="./../fitness/workout-plan.html">Workout Plan</a></strong> - Exercises to log and progress</li><li><strong><a href="./equipment.html">Equipment Guide</a></strong> - Tools to support your tracking</li></ul>',43)])])}const u=r(a,[["render",t]]);export{m as __pageData,u as default};
